// Get booking date and time from webhook
const bookingDate = $('Cancellation').first().json.body.args.booking_date; // e.g. "2025-09-25" or "09/25/2025"
const bookingTime = $('Cancellation').first().json.body.args.booking_time; // e.g. "13:00" or "1:00 PM"

// Set your desired timezone offset (IST is +05:30)
const timezoneOffsetMinutes = 5 * 60 + 30; // 5 hours 30 minutes

// Helper function to parse date and time into a Date object
function parseDateTime(date, time) {
  let year, month, day, hours = 0, minutes = 0;

  // Parse date
  if (date.includes('-')) {
    [year, month, day] = date.split('-').map(Number); // YYYY-MM-DD
  } else if (date.includes('/')) {
    const parts = date.split('/').map(Number); // MM/DD/YYYY or DD/MM/YYYY
    if (parts[0] > 12) {
      [day, month, year] = parts; // DD/MM/YYYY
    } else {
      [month, day, year] = parts; // MM/DD/YYYY
    }
  } else {
    throw new Error('Invalid date format');
  }

  // Parse time
  if (time) {
    let t = time.toUpperCase().trim();
    if (t.includes('AM') || t.includes('PM')) {
      const timeParts = t.replace(/[APM]/g, '').split(':');
      hours = parseInt(timeParts[0]);
      minutes = parseInt(timeParts[1] || 0);
      if (t.includes('PM') && hours !== 12) hours += 12;
      if (t.includes('AM') && hours === 12) hours = 0;
    } else {
      const timeParts = t.split(':');
      hours = parseInt(timeParts[0]);
      minutes = parseInt(timeParts[1] || 0);
    }
  }

  return { year, month, day, hours, minutes };
}

// Helper to format into ISO with timezone offset (without changing local time)
function toISOWithOffset({ year, month, day, hours, minutes }, offsetMinutes) {
  const pad = (n) => n.toString().padStart(2, '0');
  const sign = offsetMinutes >= 0 ? '+' : '-';
  const absOffset = Math.abs(offsetMinutes);
  const offsetHrs = pad(Math.floor(absOffset / 60));
  const offsetMins = pad(absOffset % 60);

  return `${year}-${pad(month)}-${pad(day)}T${pad(hours)}:${pad(minutes)}:00${sign}${offsetHrs}:${offsetMins}`;
}

// Parse start datetime
const startParts = parseDateTime(bookingDate, bookingTime);
const startISO = toISOWithOffset(startParts, timezoneOffsetMinutes);

// Compute end datetime (+1.5 hours = 90 minutes)
let endDateObj = new Date(startParts.year, startParts.month - 1, startParts.day, startParts.hours, startParts.minutes);
endDateObj = new Date(endDateObj.getTime() + 90 * 60 * 1000);
const endParts = {
  year: endDateObj.getFullYear(),
  month: endDateObj.getMonth() + 1,
  day: endDateObj.getDate(),
  hours: endDateObj.getHours(),
  minutes: endDateObj.getMinutes()
};
const endISO = toISOWithOffset(endParts, timezoneOffsetMinutes);

// Return result in n8n Code node format
return [
  {
    json: {
      start: startISO,   // e.g., 2025-09-25T13:00:00+05:30
      end: endISO,       // e.g., 2025-09-25T14:30:00+05:30
      originalDate: bookingDate,
      originalTime: bookingTime
    }
  }
];

