// n8n Code Node - Extract Date from ISO DateTime String

// Function to extract date from ISO format
function extractDateFromISO(isoString) {
  // Regex pattern to match YYYY-MM-DD format
  const dateRegex = /\d{4}-(?:0[1-9]|1[0-2])-(?:0[1-9]|[12]\d|3[01])/;

  // Check if input is valid
  if (!isoString || typeof isoString !== 'string') {
    return null;
  }

  // Extract the date
  const match = isoString.match(dateRegex);
  return match ? match[0] : null;
}

// Main processing logic
const items = $input.all();
const processedItems = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];

  // Extract date from different possible field names
  // Adjust these field names based on your data structure
  const isoDateString = item.json.created_at || 
                       item.json.updated_at || 
                       item.json.timestamp || 
                       item.json.date ||
                       item.json.datetime;

  // Extract the date
  const extractedDate = extractDateFromISO(isoDateString);

  // Create new item with extracted date
  const newItem = {
    json: {
      ...item.json,
      original_datetime: isoDateString,
      extracted_date: extractedDate,
      extraction_success: extractedDate !== null
    }
  };

  processedItems.push(newItem);
}

return processedItems;

