// Helper functions
function parseTimeToMinutes(timeStr) {
  const [hours, minutes] = timeStr.split(":").map(Number);
  return hours * 60 + minutes;
}

function minutesToTimeStr(totalMinutes) {
  totalMinutes = ((totalMinutes % (24 * 60)) + (24 * 60)) % (24 * 60); // wrap around midnight
  const h = Math.floor(totalMinutes / 60);
  const m = totalMinutes % 60;
  return `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}`;
}

function circularDiff(a, b) {
  const d = Math.abs(a - b);
  return Math.min(d, 24 * 60 - d); // minimal difference considering midnight
}

// ---------------- MAIN ----------------
const sheetData = $('Get row(s) in sheet2').all(); // all rows
const webhookTimeStr = $('Booking').item.json.body.args.booking_time;
const webhookMinutes = parseTimeToMinutes(webhookTimeStr);

let matches = [];

for (const row of sheetData) {
  const bookingTimeStr = row.json.booking_time;
  if (!bookingTimeStr) continue;

  const bookingMinutes = parseTimeToMinutes(bookingTimeStr);

  // Add 90 minutes
  const bookingEnd = (bookingMinutes + 90) % (24 * 60);

  // Difference with webhook
  const diff = circularDiff(bookingEnd, webhookMinutes);

  // Match if gap is at least 30 minutes
  if (diff >= 30) {
    matches.push({
      table_id: row.json.table_id,
      booking_time: bookingTimeStr,
      booking_end: minutesToTimeStr(bookingEnd),
      webhook_time: webhookTimeStr,
      gap_minutes: diff
    });
  }
}

// Return matches or false
return matches.length > 0 ? matches : [{ match: false }];

// Get the table_id from previous match
const tableId = $input.first().json.table_id;

// Get new booking data from webhook
const newBookingTime = $input.first().json.booking_time; // or wherever your webhook time is
const newBookingDate = $input.first().json.booking_date; // optional

// Get the existing row data from the sheet
const sheetRows = $('Get row(s) in sheet2').all();

// Find the row with this table_id
let rowToUpdate = sheetRows.find(r => r.json.table_id === tableId);

if (!rowToUpdate) {
    return [{ json: { error: "Table_id not found in sheet" } }];
}

// Prepare new values by appending (comma separated) to existing values
const updatedBookingTimes = rowToUpdate.json.booking_times
    ? rowToUpdate.json.booking_times + `, ${newBookingTime}`
    : newBookingTime;

const updatedBookingDates = rowToUpdate.json.booking_dates
    ? rowToUpdate.json.booking_dates + `, ${newBookingDate}`
    : newBookingDate;

// Return updated row to use in "Update" Google Sheets node
return [
    {
        json: {
            table_id: tableId,
            booking_times: updatedBookingTimes,
            booking_dates: updatedBookingDates
        }
    }
];
